(() => {
  let chat;
  try {
    chat = require("agents/chat");
  } catch (e) {
    console.error("ERROR: cannot import agents/chat: " + e.message);
    process.exit(2);
  }
  const step = chat.broadcastTransition;
  if (typeof step !== "function") {
    console.error("ERROR: agents/chat has no broadcastTransition export");
    process.exit(2);
  }
  // An observed stream whose two copies of the reply interleaved.
  let state = { status: "idle" };
  const chunks = [
    { type: "start", messageId: "a1" },
    { type: "text-start", id: "t1" },
    ...["You", " can", "You", " see", " can", " see"].map((delta) => ({ type: "text-delta", id: "t1", delta }))
  ];
  for (const chunkData of chunks) {
    state = step(state, { type: "response", streamId: "s1", messageId: "tmp", chunkData }).state;
  }
  if (state.status !== "observing") {
    console.error("ERROR: expected observing state, got " + state.status);
    process.exit(2);
  }
  // The server's clean snapshot arrives, then done.
  const snapshot = [
    { id: "u1", role: "user", parts: [{ type: "text", text: "Hi" }] },
    { id: "a1", role: "assistant", parts: [{ type: "text", text: "You can see" }] }
  ];
  const done = step(state, { type: "response", streamId: "s1", messageId: "tmp", done: true });
  if (typeof done.messagesUpdate !== "function") {
    console.error("ERROR: done produced no messagesUpdate");
    process.exit(2);
  }
  const after = done.messagesUpdate(snapshot);
  const text = after
    .filter((m) => m.role === "assistant")
    .flatMap((m) => m.parts)
    .filter((p) => p.type === "text")
    .map((p) => p.text)
    .join("");
  if (text === "You can see") {
    console.log("OK: the server snapshot text is kept after done: " + JSON.stringify(text));
    process.exit(0);
  }
  if (text === "You canYou see can see") {
    console.error("FAIL: done merged the scrambled observed text over the server snapshot");
    process.exit(1);
  }
  console.error("ERROR: unexpected assistant text " + JSON.stringify(text));
  process.exit(2);
})();

